var attackAnalysisCache=null,attackAnalysisTeam=0,attackAnalysisOpen=false,attackAnalysisMarkup=null;
function readVisibleAttackAnalysis(){
 const pending=typeof motionEnabled==='function'&&motionEnabled()&&typeof lastEvent!=='undefined'&&lastEvent&&['goal','shot','chance'].includes(lastEvent.type)&&!lastEventFast&&(movementEvent!==lastEvent||movementEventAge<Movement.impactAge(lastEvent))?lastEvent:null;
 const key=state.seed+':'+state.minute+':'+state.phase+':'+state.logs.length+':'+state.statisticsOriginMinute;
 if(!attackAnalysisCache||attackAnalysisCache.match!==state||attackAnalysisCache.key!==key||attackAnalysisCache.pending!==pending)attackAnalysisCache={match:state,key,pending,model:AttackAnalysis.read(state,{pendingEvent:pending})};
 return attackAnalysisCache.model;
}
function attackAnalysisHTML(d){
 const team=attackAnalysisTeam,leader=d.leaders[team],total=d.totals[team],width=d.wide[team],scale=Math.max(1,...d.rows.map(r=>r.teams[team].chances)),rows=d.rows.map(r=>{const c=r.teams[team];return '<tr><th scope="row"><span>'+r.label+'</span><i aria-hidden="true" style="width:'+Math.round(c.chances/scale*100)+'%"></i></th><td>'+c.chances+'</td><td>'+c.blocked+'</td><td>'+c.shots+'</td><td>'+c.goals+'</td></tr>';}).join('');
 return '<details class="attack-analysis" '+(attackAnalysisOpen?'open':'')+'><summary><b>어떤 공격이 슈팅으로 이어졌나</b><span>우리 '+d.totals[0].chances+' · 상대 '+d.totals[1].chances+'기회</span></summary><div class="attack-analysis-body"><div class="attack-team-picker" role="group" aria-label="공격 경로 분석 팀">'+[0,1].map(t=>'<button type="button" data-attack-team="'+t+'" aria-pressed="'+(team===t)+'">'+(t===0?'우리 공격':'상대 공격')+'</button>').join('')+'</div><p class="attack-analysis-caption">'+(d.limited?d.origin+'분 이후 기록':d.minute+'분까지의 기록')+(d.pending?' · 재생 중 장면 제외':'')+'</p><table aria-label="'+(team===0?'우리':'상대')+' 공격 경로별 기록"><thead><tr><th scope="col">공격 경로</th><th scope="col">기회</th><th scope="col">차단</th><th scope="col">슈팅</th><th scope="col">골</th></tr></thead><tbody>'+rows+'</tbody><tfoot><tr><th scope="row">기록 합계</th><td>'+total.chances+'</td><td>'+total.blocked+'</td><td>'+total.shots+'</td><td>'+total.goals+'</td></tr></tfoot></table><div class="attack-coach-note"><b>'+(leader?'가장 자주 기록된 전개 · '+leader.label:total.chances?'여러 경로로 골문을 노렸습니다':'첫 공격 기회를 기다립니다')+'</b><p>'+(leader?leader.chances+'기회에서 '+leader.shots+'슈팅·'+leader.goals+'골입니다. 현재 선수 체력과 상대 배치를 함께 보고 다음 지시를 정하세요.':total.chances?'가장 많은 기회를 만든 경로가 동률입니다. 각 경로의 슈팅과 득점을 비교하세요.':'기회가 기록되면 전개 유형별 차단·슈팅·득점을 비교할 수 있습니다.')+'</p><span>크로스·컷백 기회 방향 · 왼쪽 '+width.left+' / 오른쪽 '+width.right+'</span></div><p class="attack-analysis-caption">'+escapeText(d.note)+(d.unclassified.some(Boolean)?' 경로 미확인: 우리 '+d.unclassified[0]+' / 상대 '+d.unclassified[1]+'.':'')+'</p><div class="attack-analysis-actions">'+(state.phase!=='full'?'<button type="button" class="secondary" data-attack-target="analysis">전술 전개와 비교</button>':'')+'<button type="button" class="secondary" data-attack-target="opponent">상대 선발 확인</button></div></div></details>';
}
function renderAttackAnalysis(){
 if(view!=='match'||matchPopupActive!=='stats'||!state)return;
 const host=$('attack-analysis-panel');if(!host)return;const detail=host.querySelector('details');if(detail)attackAnalysisOpen=detail.open;
 const d=readVisibleAttackAnalysis();if(!d.valid){host.hidden=true;return;}host.hidden=false;
 const html=attackAnalysisHTML(d);if(attackAnalysisMarkup===html&&host.innerHTML===html)return;
 const focused=host.contains(document.activeElement)?document.activeElement:null,focusTeam=focused?.dataset.attackTeam;host.innerHTML=html;attackAnalysisMarkup=html;
 if(focusTeam!==undefined)host.querySelector('[data-attack-team="'+focusTeam+'"]')?.focus({preventScroll:true});
 host.onclick=e=>{const choice=e.target.closest('[data-attack-team]'),target=e.target.closest('[data-attack-target]');if(choice&&['0','1'].includes(choice.dataset.attackTeam)){attackAnalysisTeam=Number(choice.dataset.attackTeam);renderAttackAnalysis();host.querySelector('[data-attack-team="'+attackAnalysisTeam+'"]')?.focus({preventScroll:true});}else if(target&&['analysis','opponent'].includes(target.dataset.attackTarget)&&!(target.dataset.attackTarget==='analysis'&&state.phase==='full'))openMatchPopup(target.dataset.attackTarget,target);};
}
const attackAnalysisPanel=document.createElement('section');attackAnalysisPanel.id='attack-analysis-panel';$('matchday-summary').after(attackAnalysisPanel);
const attackOriginalPopup=renderMatchPopup;renderMatchPopup=function(){attackOriginalPopup();renderAttackAnalysis();};
